#include "Physics/V5/XPBDPhysicsSystem.h"
#include "Runtime/GameplayPhysicsBody.h"
#include "Runtime/GameplayPhysicsQuery.h"
#include "Threading/JobSystem.h"

#include <cmath>
#include <cstdio>
#include <limits>

int main() {
    using namespace NeoEngine;
    JobSystem::Get().Initialize(2); const auto fail=[](const char* stage) { std::fprintf(stderr,"GAMEPLAY_PHYSICS_BODY_FAIL %s\n",stage); JobSystem::Get().Shutdown(); return 1; }; ArchetypeManager entities; GameplayPhysicsBodyBuilder builder; EntityID dynamic=999, dynamicTwo=999, statik=999;
    if(!builder.CreateCircleBody(entities,{GameplayPhysicsBodyType::Dynamic,2,0,3,0,0.5F,2},dynamic)||builder.LastError()!=GameplayPhysicsBodyError::None||dynamic==999||!builder.CreateCircleBody(entities,{GameplayPhysicsBodyType::Dynamic,8,0,0,0,0.5F,1},dynamicTwo)||dynamicTwo==999||!builder.CreateCircleBody(entities,{GameplayPhysicsBodyType::Static,5,0,0,0,1,0},statik)||statik==999)return fail("create");
    GameplayCircleBodySnapshot snapshot{}; if(!builder.SnapshotCircleBody(entities,dynamic,snapshot)||builder.LastError()!=GameplayPhysicsBodyError::None||snapshot.type!=GameplayPhysicsBodyType::Dynamic||std::fabs(snapshot.positionX-2.0F)>0.001F||std::fabs(snapshot.velocityX-3.0F)>0.001F||std::fabs(snapshot.inverseMass-0.5F)>0.001F)return fail("snapshotDynamic"); if(!builder.SnapshotCircleBody(entities,statik,snapshot)||snapshot.type!=GameplayPhysicsBodyType::Static||snapshot.velocityX!=0.0F||snapshot.inverseMass!=0.0F)return fail("snapshotStatic");
    const uint64_t beforeVelocity=entities.GetPhysicsRevision(); if(!builder.SetDynamicPlanarVelocity(entities,dynamic,-2.0F,1.5F)||builder.LastError()!=GameplayPhysicsBodyError::None||entities.GetPhysicsRevision()!=beforeVelocity+1U||!builder.SnapshotCircleBody(entities,dynamic,snapshot)||std::fabs(snapshot.velocityX+2.0F)>0.001F||std::fabs(snapshot.velocityZ-1.5F)>0.001F)return fail("velocity"); const uint64_t beforeBatch=entities.GetPhysicsRevision(); const std::vector<GameplayPlanarVelocityCommand> batch{{dynamic,4.0F,-3.0F},{dynamicTwo,-1.0F,2.0F}}; if(!builder.SetDynamicPlanarVelocitySet(entities,batch)||builder.LastError()!=GameplayPhysicsBodyError::None||entities.GetPhysicsRevision()!=beforeBatch+1U||!builder.SnapshotCircleBody(entities,dynamic,snapshot)||std::fabs(snapshot.velocityX-4.0F)>0.001F||std::fabs(snapshot.velocityZ+3.0F)>0.001F||!builder.SnapshotCircleBody(entities,dynamicTwo,snapshot)||std::fabs(snapshot.velocityX+1.0F)>0.001F||std::fabs(snapshot.velocityZ-2.0F)>0.001F)return fail("batch"); const uint64_t validRevision=entities.GetPhysicsRevision(); EntityID preserved=statik; GameplayCircleBodySnapshot preservedSnapshot{GameplayPhysicsBodyType::Dynamic,9,8,7,6,5,4}; const std::vector<GameplayPlanarVelocityCommand> staticBatch{{dynamic,7.0F,7.0F},{statik,1.0F,1.0F}}; const std::vector<GameplayPlanarVelocityCommand> duplicateBatch{{dynamic,7.0F,7.0F},{dynamic,1.0F,1.0F}}; std::vector<GameplayPlanarVelocityCommand> oversized(GameplayPhysicsBodyBuilder::kMaxVelocityCommands+1U,{dynamic,1.0F,1.0F}); if(builder.CreateCircleBody(entities,{GameplayPhysicsBodyType::Dynamic,0,0,0,0,-1,1},statik)||builder.LastError()!=GameplayPhysicsBodyError::InvalidConfiguration||statik!=preserved||entities.GetPhysicsRevision()!=validRevision||builder.SetDynamicPlanarVelocitySet(entities,staticBatch)||builder.LastError()!=GameplayPhysicsBodyError::StaticBody||entities.GetPhysicsRevision()!=validRevision||!builder.SnapshotCircleBody(entities,dynamic,snapshot)||std::fabs(snapshot.velocityX-4.0F)>0.001F||builder.SetDynamicPlanarVelocitySet(entities,duplicateBatch)||builder.LastError()!=GameplayPhysicsBodyError::DuplicateBody||entities.GetPhysicsRevision()!=validRevision||builder.SetDynamicPlanarVelocitySet(entities,oversized)||builder.LastError()!=GameplayPhysicsBodyError::Capacity||entities.GetPhysicsRevision()!=validRevision||builder.SetDynamicPlanarVelocitySet(entities,{{dynamic,std::nanf(""),0.0F}})||builder.LastError()!=GameplayPhysicsBodyError::InvalidConfiguration||entities.GetPhysicsRevision()!=validRevision||builder.SetDynamicPlanarVelocity(entities,statik,1.0F,1.0F)||builder.LastError()!=GameplayPhysicsBodyError::StaticBody||entities.GetPhysicsRevision()!=validRevision||builder.SetDynamicPlanarVelocity(entities,dynamic,std::nanf(""),0.0F)||builder.LastError()!=GameplayPhysicsBodyError::InvalidConfiguration||entities.GetPhysicsRevision()!=validRevision||builder.SetDynamicPlanarVelocity(entities,99999U,1.0F,1.0F)||builder.LastError()!=GameplayPhysicsBodyError::UnknownBody||entities.GetPhysicsRevision()!=validRevision||builder.SnapshotCircleBody(entities,99999U,preservedSnapshot)||builder.LastError()!=GameplayPhysicsBodyError::UnknownBody||preservedSnapshot.positionX!=9.0F||preservedSnapshot.inverseMass!=4.0F)return fail("invalid");
    const uint64_t impulseBefore=entities.GetPhysicsRevision(); if(!builder.ApplyDynamicPlanarImpulse(entities,dynamic,2.0F,-4.0F)||entities.GetPhysicsRevision()!=impulseBefore+1U||!builder.SnapshotCircleBody(entities,dynamic,snapshot)||std::fabs(snapshot.velocityX-5.0F)>0.001F||std::fabs(snapshot.velocityZ+5.0F)>0.001F||!builder.ApplyDynamicPlanarImpulseSet(entities,{{dynamic,2.0F,-4.0F},{dynamicTwo,1.0F,-1.0F}})||!builder.SnapshotCircleBody(entities,dynamic,snapshot)||std::fabs(snapshot.velocityX-6.0F)>0.001F||std::fabs(snapshot.velocityZ+7.0F)>0.001F||!builder.SnapshotCircleBody(entities,dynamicTwo,snapshot)||std::fabs(snapshot.velocityX)>0.001F||std::fabs(snapshot.velocityZ-1.0F)>0.001F)return fail("impulse"); const uint64_t impulseRevision=entities.GetPhysicsRevision(); if(builder.ApplyDynamicPlanarImpulseSet(entities,{{dynamic,1.0F,1.0F},{statik,1.0F,1.0F}})||builder.LastError()!=GameplayPhysicsBodyError::StaticBody||entities.GetPhysicsRevision()!=impulseRevision||builder.ApplyDynamicPlanarImpulseSet(entities,{{dynamic,1.0F,1.0F},{dynamic,1.0F,1.0F}})||builder.LastError()!=GameplayPhysicsBodyError::DuplicateBody||entities.GetPhysicsRevision()!=impulseRevision||builder.ApplyDynamicPlanarImpulse(entities,dynamic,std::nanf(""),0.0F)||builder.LastError()!=GameplayPhysicsBodyError::InvalidConfiguration||entities.GetPhysicsRevision()!=impulseRevision)return fail("impulseReject");
    bool dynamicOk=false, staticOk=false; for(ArchetypeChunk* chunk:entities.GetChunks<PositionComponent,VelocityComponent,ColliderComponent>()) for(size_t i=0;i<chunk->count;++i) { if(chunk->entities[i]==dynamic) dynamicOk=std::fabs(chunk->posX[i]-2.0F)<0.001F&&std::fabs(chunk->velX[i]-6.0F)<0.001F&&std::fabs(chunk->velZ[i]+7.0F)<0.001F&&std::fabs(chunk->radius[i]-0.5F)<0.001F&&std::fabs(chunk->invMass[i]-0.5F)<0.001F; if(chunk->entities[i]==statik) staticOk=std::fabs(chunk->posX[i]-5.0F)<0.001F&&chunk->velX[i]==0.0F&&chunk->invMass[i]==0.0F; }
    XPBDPhysicsSystem physics; physics.Step(entities,1.0F/60.0F); GameplayPhysicsQuery query; GameplayRayHit2 hit{}; if(!dynamicOk||!staticOk||!query.Raycast(physics,{0,0,1,0,10,COLLISION_LAYER_DEFAULT},hit)||hit.entity!=dynamic)return fail("query");
    if(!builder.SetDynamicPlanarVelocity(entities,dynamic,std::numeric_limits<float>::max(),0.0F)||builder.ApplyDynamicPlanarImpulse(entities,dynamic,std::numeric_limits<float>::max(),0.0F)||builder.LastError()!=GameplayPhysicsBodyError::VelocityOverflow||!builder.SnapshotCircleBody(entities,dynamic,snapshot)||snapshot.velocityX!=std::numeric_limits<float>::max())return fail("impulseOverflow"); JobSystem::Get().Shutdown(); std::printf("GAMEPLAY_PHYSICS_BODY_SMOKE_OK dynamic=2 static=1 snapshot=1 velocity=1 impulse=1 batch=1 ecs=1 query=1 invalid=1\n"); return 0;
}
